const sorted = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91];

function binarySearch(xs, target) {
  let lo = 0;
  let hi = xs.length - 1;
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    console.log("window", lo, "..", hi, "probe", mid, "=", xs[mid]);
    if (xs[mid] === target) return mid;
    if (xs[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}

console.log("found at", binarySearch(sorted, 23));
console.log("found at", binarySearch(sorted, 7));

