function worstCaseProbes(n) {
  let lo = 0;
  let hi = n - 1;
  let probes = 0;
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    probes += 1;
    lo = mid + 1;
  }
  return probes;
}

for (const n of [1, 2, 4, 8, 16, 1000, 1000000]) {
  console.log(n, worstCaseProbes(n), Math.floor(Math.log2(n)) + 1);
}

let calls = 0;

function maxOf(xs, lo, hi) {
  calls += 1;
  if (lo === hi) return xs[lo];
  const mid = lo + Math.floor((hi - lo) / 2);
  const left = maxOf(xs, lo, mid);
  const right = maxOf(xs, mid + 1, hi);
  return left > right ? left : right;
}

const data = [3, 9, 4, 1, 7, 8, 2, 6];
console.log(maxOf(data, 0, data.length - 1));
console.log("calls", calls);

