function firstIndexOf(xs, target) {
  let lo = 0;
  let hi = xs.length - 1;
  let best = -1;
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (xs[mid] === target) {
      best = mid;
      hi = mid - 1;
    } else if (xs[mid] < target) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return best;
}

